const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const n = nextInt();
    if (n === null) return;

    const a = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        a[i] = nextInt();
    }

    let invisibleCount = 0;
    let maxHeight = a[n - 1];

    for (let i = n - 2; i >= 0; i--) {
        if (a[i] <= maxHeight) {
            invisibleCount++;
        } else {
            maxHeight = a[i];
        }
    }

    console.log(invisibleCount);
}

solve();
